-- ============================================================
-- 940 — 851'de "şık ipucu" nedeniyle pasife alınan 110 genel_kultur sorusu: şıklar düzeltildi, geri açıldı
-- (2 Eki 2026, Ida)
--
-- 851 bu 110 soruyu doğru şık çeldiricilerden belirgin uzun / tek çok kelimeli olduğu ya da Jev'in
-- soru metnini görmeden doğru şıkkı bulduğu için pasife almıştı. Bu migration:
--   • 93 sorunun YANLIŞ şıklarını yeniden yazar (doğru şıkla aynı uzunluk, biçim ve ayrıntı düzeyi) ve
--     aktif = true yapar. Soru metni, doğru cevap ve doğru şıkkın indeksi DEĞİŞMEZ
--     (match_answers.cevap indeksle tutulur; şık sırası karışmaz).
--   • 17 soruya DOKUNMAZ (pasif kalır): aynı bilgiyi soran tekrarlar, belirsiz bir soru ve üç denemede
--     Jev "soru gizli" testini geçemeyenler. Liste: docs/IPUCU_SIKLARI_YEDEK.json › acilmayan.
--   • EN çeviri: 91 satır AYNI indekslerle güncellenir (doğru şıkkın İngilizcesi aynen); 2 sorunun
--     çeviri satırı yoktur (atasözü/deyim) → Türkçe dışı maçta zaten sorulmaz.
--   • sik_ipucu_jev işareti (35 soruda vardı) kaldırılır: yeni şıklar aynı Jev testinden geçti
--     (soru_denetim/kapi.mjs › sikIpucuTesti, doğru şıkka <= 0,8). Kural işaretleri tetikleyicide yeniden hesaplanır.
-- Yalnız questions.secenekler / aktif / supheli_isaretler ve question_translations.secenekler yazılır.
-- Eski şıklar ve geri alma: docs/IPUCU_SIKLARI_YEDEK.json.
-- Koruma: yalnız hâlâ genel_kultur'da, pasif ve eski şıkları taşıyan satırlar; biri bile farklıysa hiçbiri yazılmaz.
-- ============================================================

-- Elle işaret (sik_ipucu_jev) tetikleyicide korunur; bilerek kaldırmak için (298):
select set_config('app.soru_elle_isaret_yaz', 'on', true);

create temp table _ipucu_sik (id uuid primary key, dogru smallint, eski_tr jsonb, yeni_tr jsonb, eski_en jsonb, yeni_en jsonb) on commit drop;

do $$
declare v_n int; v_beklenen int := (select count(*) from _ipucu_sik);
begin
  -- Yalnız 851'in bıraktığı hâldeki satırlar (araya başka düzeltme girdiyse dur)
  select count(*) into v_n from public.questions q join _ipucu_sik s on s.id = q.id
   where q.secenekler = s.eski_tr and q.dogru_cevap = s.dogru and q.aktif = false and q.kategori = 'genel_kultur';
  if v_n <> v_beklenen then
    raise exception '940: % sorudan % tanesi beklenen eski hâlde (pasif, genel_kultur, eski şıklar)', v_beklenen, v_n;
  end if;

  -- Yeni şık dizileri: 4 şık, doğru şık metni aynı yerde
  select count(*) into v_n from _ipucu_sik s
   where jsonb_array_length(s.yeni_tr) <> 4 or s.yeni_tr -> s.dogru::int is distinct from s.eski_tr -> s.dogru::int
      or (s.yeni_en is not null and (jsonb_array_length(s.yeni_en) <> 4 or s.yeni_en -> s.dogru::int is distinct from s.eski_en -> s.dogru::int));
  if v_n > 0 then
    raise exception '940: % satırda yeni şık dizisi bozuk (4 şık / doğru şık aynı değil)', v_n;
  end if;

  update public.questions q
     set secenekler = s.yeni_tr,
         supheli_isaretler = array_remove(q.supheli_isaretler, 'sik_ipucu_jev'),
         aktif = true
    from _ipucu_sik s
   where q.id = s.id;

  -- EN çeviri: aynı indekslerle; eski çeviri beklenen hâlde değilse dur (yeni TR + eski EN birlikte kalmasın)
  update public.question_translations t
     set secenekler = s.yeni_en
    from _ipucu_sik s
   where t.question_id = s.id and t.dil = 'en' and s.yeni_en is not null and t.secenekler = s.eski_en;
  get diagnostics v_n = row_count;
  if v_n <> (select count(*) from _ipucu_sik where yeni_en is not null) then
    raise exception '940: EN çeviri % satır güncellendi, beklenen %', v_n, (select count(*) from _ipucu_sik where yeni_en is not null);
  end if;
  -- EN'i yazılmayan soruda çeviri satırı olmamalı
  select count(*) into v_n from public.question_translations t join _ipucu_sik s on s.id = t.question_id where s.yeni_en is null;
  if v_n > 0 then
    raise exception '940: % soruda çeviri satırı var ama yeni çeviri şıkkı yok', v_n;
  end if;

  -- Sonuç: sik_ipucu_jev kalmamalı, rekabetçi havuzdan düşüren kural işareti olmamalı
  select count(*) into v_n from public.questions q join _ipucu_sik s on s.id = q.id
   where 'sik_ipucu_jev' = any(q.supheli_isaretler) or q.supheli_agirlik >= public.ayar_sayi('soru_rekabetci_haric_agirlik', 2);
  if v_n > 0 then
    raise exception '940: % soruda işaret/ağırlık kaldı', v_n;
  end if;
end $$;

select set_config('app.soru_elle_isaret_yaz', '', true);
